-- Additive stage 2. Existing profile/appearance and financial records are retained.
begin;
create table kiyi_private.stage2_backup(key text primary key, value text not null);
alter table kiyi_private.stage2_backup enable row level security;
revoke all on kiyi_private.stage2_backup from public,anon,authenticated;
insert into kiyi_private.stage2_backup values ('command',pg_get_functiondef('kiyi_private.command(text,jsonb)'::regprocedure));
create table public.kiyi_vehicle_models(id text primary key,name text not null,kind text not null check(kind in ('car','motorcycle')),body text not null,ready boolean not null default false,parts jsonb not null default '{}');
alter table public.kiyi_vehicle_models enable row level security;
create policy catalog_read on public.kiyi_vehicle_models for select to authenticated using(true);
grant select on public.kiyi_vehicle_models to authenticated;
