create table public.kiyi_vehicles(
 id uuid primary key default gen_random_uuid(),owner uuid not null references auth.users(id) on delete cascade,
 kind text not null check(kind in ('car','motorcycle')),model_id text references public.kiyi_vehicle_models(id),
 plate text,plate_key text generated always as (nullif(regexp_replace(upper(plate),'[[:space:]]','','g'),'')) stored,
 description text not null default '' check(length(description)<=1000),is_primary boolean not null default false,
 verification text not null default 'unverified' check(verification in ('unverified','pending','approved')),
 created_at timestamptz not null default now(),deleted_at timestamptz,unique(id,owner));
create unique index kiyi_vehicle_plate_unique on public.kiyi_vehicles(plate_key) where deleted_at is null;
create unique index kiyi_vehicle_primary_unique on public.kiyi_vehicles(owner) where is_primary and deleted_at is null;
create index kiyi_vehicle_owner_idx on public.kiyi_vehicles(owner,created_at desc) where deleted_at is null;
create table public.kiyi_vehicle_customizations(vehicle_id uuid primary key references public.kiyi_vehicles on delete cascade,appearance jsonb not null default '{}',version integer not null default 1,updated_at timestamptz not null default now(),check(jsonb_typeof(appearance)='object' and octet_length(appearance::text)<10000));
alter table public.kiyi_vehicles enable row level security;
alter table public.kiyi_vehicle_customizations enable row level security;
-- No direct client writes or broad SELECT. Existing authenticated command remains the boundary.
revoke all on public.kiyi_vehicles,public.kiyi_vehicle_customizations from public,anon,authenticated;
insert into public.kiyi_vehicles(owner,kind,model_id,plate,is_primary,verification)
select p.user_id,'car',a.vehicle_model,p.profile->>'plate',true,case when v.status='approved' then 'approved' else 'unverified' end from public.kiyi_profiles p left join public.kiyi_appearance a using(user_id) left join public.kiyi_verifications v using(user_id) where p.deleted_at is null;
insert into public.kiyi_vehicle_customizations(vehicle_id,appearance)
select v.id,jsonb_build_object('paint',coalesce(a.paint,'#ffffff'),'plateStyle',coalesce(a.plate_style,'classic'),'plateNames',coalesce(a.plate_names,'{}'),'frame',coalesce(a.frame,'none'),'vehicleModel',a.vehicle_model) from public.kiyi_vehicles v left join public.kiyi_appearance a on a.user_id=v.owner;
-- Lift obsolete seven-model constraint; canonical catalog validates the command below.
alter table public.kiyi_appearance drop constraint kiyi_vehicle_model_allowlist;
alter table public.kiyi_appearance add constraint kiyi_vehicle_model_catalog_fk foreign key(vehicle_model) references public.kiyi_vehicle_models(id);
create table kiyi_private.media_limits(id boolean primary key default true check(id),image_bytes bigint not null default 5242880,video_bytes bigint not null default 20971520,user_bytes bigint not null default 52428800,project_bytes bigint not null default 524288000,max_per_post int not null default 1);
insert into kiyi_private.media_limits default values;
alter table kiyi_private.media_limits enable row level security;
create table kiyi_private.media_registry(path text primary key,owner uuid not null references auth.users on delete cascade,mime text not null,bytes bigint not null check(bytes>0),state text not null default 'pending' check(state in ('pending','ready','deleting')),created_at timestamptz not null default now(),checked_at timestamptz);
alter table kiyi_private.media_registry enable row level security;
create table kiyi_private.media_cleanup(path text primary key,owner uuid not null,created_at timestamptz not null default now(),attempts int not null default 0);
alter table kiyi_private.media_cleanup enable row level security;
create table kiyi_private.media_signing_secret(id boolean primary key default true check(id),secret text not null);
alter table kiyi_private.media_signing_secret enable row level security;
revoke all on kiyi_private.media_limits,kiyi_private.media_registry,kiyi_private.media_cleanup,kiyi_private.media_signing_secret from public,anon,authenticated;
update storage.buckets set file_size_limit=20971520,allowed_mime_types=array['image/jpeg','image/png','image/webp','audio/webm','audio/mp4','video/mp4','video/webm'] where id='kiyi-media';
create function kiyi_private.social_upload_allowed(path text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from kiyi_private.media_registry r where r.path=path and r.owner=auth.uid() and r.state='pending' and r.created_at>now()-interval '30 minutes')$$;
revoke all on function kiyi_private.social_upload_allowed(text) from public;grant execute on function kiyi_private.social_upload_allowed(text) to authenticated;
create policy kiyi_social_reservation on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'kiyi-media' or split_part(name,'/',2)<>'social' or kiyi_private.social_upload_allowed(name));
create function kiyi_private.queue_post_media() returns trigger language plpgsql security definer set search_path='' as $$begin
 if old.media is not null then insert into kiyi_private.media_cleanup(path,owner) values(old.media,old.author) on conflict do nothing; update kiyi_private.media_registry set state='deleting' where path=old.media;end if;return old;end$$;
revoke all on function kiyi_private.queue_post_media() from public,anon,authenticated;
create trigger kiyi_deleted_post_media after delete on public.kiyi_posts for each row execute function kiyi_private.queue_post_media();
-- Retain complete previous command for controlled rollback and backwards-compatible dispatch.
alter function kiyi_private.command(text,jsonb) rename to command_stage1;
create function kiyi_private.command(action text,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare u uuid=auth.uid();v public.kiyi_vehicles;m public.kiyi_vehicle_models;r jsonb;a jsonb;vid uuid;lim kiyi_private.media_limits;path text;mime text;n bigint;signature text;expected text;postid uuid;
begin
 if u is null or not kiyi_private.account_active(u) then raise exception 'Giriş yapmalısın.' using errcode='42501';end if;
 -- Reuse suspension, account deletion and maintenance guards from the existing command.
 perform kiyi_private.command_stage1('bundle','{}');
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 if not exists(select 1 from public.kiyi_vehicles where owner=u and is_primary and deleted_at is null) then
  insert into public.kiyi_vehicles(owner,kind,plate,is_primary) select u,'car',profile->>'plate',true from public.kiyi_profiles where user_id=u returning id into vid;
  insert into public.kiyi_vehicle_customizations(vehicle_id,appearance) select vid,jsonb_build_object('paint',paint,'plateStyle',plate_style,'plateNames',plate_names,'frame',frame,'vehicleModel',vehicle_model) from public.kiyi_appearance where user_id=u;
 end if;
 if action='post_create' and nullif(trim(coalesce(payload->>'text','')),'') is null and nullif(payload->>'media','') is null and nullif(payload->'music','null') is null and nullif(payload->'poll','null') is null then raise exception 'Boş gönderi oluşturulamaz.';end if;
 if action='comment' and length(trim(coalesce(payload->>'text',''))) not between 1 and 1000 then raise exception 'Yorum 1–1000 karakter olmalı.';end if;
 if action='garage_list' then return jsonb_build_object('vehicles',coalesce((select jsonb_agg(to_jsonb(z)) from(select v.*,c.appearance,c.version,m.ready from public.kiyi_vehicles v join public.kiyi_vehicle_customizations c on c.vehicle_id=v.id left join public.kiyi_vehicle_models m on m.id=v.model_id where v.owner=u and v.deleted_at is null order by v.created_at)z),'[]'));
 elsif action='vehicle_create' then
  select * into m from public.kiyi_vehicle_models where id=payload->>'model';if not found then raise exception 'Geçersiz model.' using errcode='22023';end if;
  if length(trim(coalesce(payload->>'plate','')))=0 or length(payload->>'plate')>30 then raise exception 'Plaka gerekiyor.';end if;
  perform pg_advisory_xact_lock(hashtextextended('plate:'||regexp_replace(upper(payload->>'plate'),'[[:space:]]','','g'),0));
  if exists(select 1 from public.kiyi_profiles where user_id<>u and deleted_at is null and plate_key=regexp_replace(upper(payload->>'plate'),'[[:space:]]','','g')) then raise exception 'Bu plaka başka hesaba bağlı.';end if;
  insert into public.kiyi_vehicles(owner,kind,model_id,plate,description) values(u,m.kind,m.id,payload->>'plate',coalesce(payload->>'description','')) returning * into v;
  insert into public.kiyi_vehicle_customizations(vehicle_id) values(v.id);return to_jsonb(v);
 elsif action in ('vehicle_customize','vehicle_model') then
  if payload?'target' and (payload->>'target')::uuid<>u then raise exception 'Yetkisiz işlem.' using errcode='42501';end if;
  select * into v from public.kiyi_vehicles where owner=u and deleted_at is null and (case when payload?'vehicle_id' then id=(payload->>'vehicle_id')::uuid else is_primary end) for update;
  if not found then raise exception 'Araç bulunamadı.' using errcode='42501';end if;
  select * into m from public.kiyi_vehicle_models where id=coalesce(payload->>'model',v.model_id);if not found or not m.ready or m.kind<>v.kind then raise exception 'Model katmanları henüz hazır değil.' using errcode='22023';end if;
  if action='vehicle_model' then update public.kiyi_vehicles set model_id=m.id where id=v.id;update public.kiyi_vehicle_customizations set appearance=appearance||jsonb_build_object('vehicleModel',m.id),version=version+1 where vehicle_id=v.id;
   if v.is_primary then update public.kiyi_appearance set vehicle_model=m.id where user_id=u;update public.kiyi_profiles set profile=profile||jsonb_build_object('car',m.name) where user_id=u;end if;
   return jsonb_build_object('ok',true,'vehicleModel',m.id,'vehicle_id',v.id);
  end if;
  a=payload->'appearance';if jsonb_typeof(a) is distinct from 'object' or octet_length(a::text)>8000 then raise exception 'Geçersiz özelleştirme.';end if;
  if exists(select 1 from jsonb_object_keys(a)k where k not in ('paint','plateStyle','plateNames','vehicleModel','frame','wrap','rim','accessories')) then raise exception 'Geçersiz parça.';end if;
  -- Paid properties stay behind existing purchase/inventory logic, never arbitrary JSON writes.
  if a ?| array['paint','plateStyle','plateNames','frame','vehicleModel'] then raise exception 'Ücretli görünümü mevcut satın alma işlemiyle değiştir.';end if;
  if a?'accessories' and (jsonb_typeof(a->'accessories')<>'object' or octet_length((a->'accessories')::text)>500) then raise exception 'Geçersiz aksesuar.';end if;
  if coalesce((payload->>'version')::int,0)<>(select version from public.kiyi_vehicle_customizations where vehicle_id=v.id) then raise exception 'Araç güncellenmiş. Yeniden yükle.' using errcode='40001';end if;
  update public.kiyi_vehicle_customizations set appearance=appearance||a,version=version+1,updated_at=now() where vehicle_id=v.id;return jsonb_build_object('ok',true);
 elsif action='media_reserve' then
  select * into lim from kiyi_private.media_limits;mime=payload->>'mime';n=(payload->>'bytes')::bigint;
  if mime not in ('image/jpeg','image/png','image/webp','video/mp4','video/webm') or n<=0 or n>(case when mime like 'video/%' then lim.video_bytes else lim.image_bytes end) then raise exception 'Dosya türü veya boyutu uygun değil.';end if;
  perform pg_advisory_xact_lock(hashtextextended('kiyi-media-quota',0));
  if (select count(*) from kiyi_private.media_registry where owner=u and created_at>now()-interval '1 hour')>=30 then raise exception 'Yükleme sınırına ulaştın.';end if;
  if coalesce((select sum(bytes) from kiyi_private.media_registry where owner=u),0)+n>lim.user_bytes or coalesce((select sum((metadata->>'size')::bigint) from storage.objects),0)+coalesce((select sum(bytes) from kiyi_private.media_registry where state='pending'),0)+n>lim.project_bytes then raise exception 'Depolama sınırına ulaşıldı.';end if;
  path=u::text||'/social/'||gen_random_uuid()::text;insert into kiyi_private.media_registry values(path,u,mime,n,'pending',now(),null);return jsonb_build_object('path',path);
 elsif action='media_confirm' then
  path=payload->>'path';select * into lim from kiyi_private.media_limits;
  if not exists(select 1 from kiyi_private.media_registry where media_registry.path=path and owner=u and state='pending' and created_at>now()-interval '30 minutes') then raise exception 'Yükleme bulunamadı.';end if;
  select encode(extensions.hmac(path||':'||(payload->>'sha256'),secret,'sha256'),'hex') into expected from kiyi_private.media_signing_secret;
  if expected is null or expected is distinct from payload->>'signature' then raise exception 'Dosya sunucu tarafından doğrulanmadı.' using errcode='42501';end if;
  if not exists(select 1 from storage.objects o join kiyi_private.media_registry r on r.path=o.name where o.bucket_id='kiyi-media' and o.name=path and (o.metadata->>'size')::bigint=r.bytes and o.metadata->>'mimetype'=r.mime) then raise exception 'Dosya bilgileri uyuşmuyor.';end if;
  update kiyi_private.media_registry set state='ready',checked_at=now() where media_registry.path=path;return jsonb_build_object('ok',true);
 elsif action='media_cleanup_list' then
  insert into kiyi_private.media_cleanup(path,owner) select path,owner from kiyi_private.media_registry where owner=u and state='pending' and created_at<now()-interval '1 hour' on conflict do nothing;
  return jsonb_build_object('paths',coalesce((select jsonb_agg(path) from kiyi_private.media_cleanup where owner=u and not exists(select 1 from public.kiyi_posts p where p.media=media_cleanup.path) and not exists(select 1 from public.kiyi_profiles p where p.profile->>'avatar'=media_cleanup.path or p.profile->>'photo'=media_cleanup.path or coalesce(p.profile->'photos','[]')?media_cleanup.path)),'[]'));
 elsif action='media_cleanup_ack' then
  path=payload->>'path';if not exists(select 1 from storage.objects where bucket_id='kiyi-media' and name=path) then delete from kiyi_private.media_cleanup where media_cleanup.path=path and owner=u;delete from kiyi_private.media_registry where media_registry.path=path and owner=u;end if;return jsonb_build_object('ok',true);
 end if;
 r=kiyi_private.command_stage1(action,payload);
 if action in ('appearance','profile') then
  update public.kiyi_vehicles set plate=p.profile->>'plate' from public.kiyi_profiles p where owner=u and p.user_id=u and is_primary and kiyi_vehicles.deleted_at is null;
  update public.kiyi_vehicle_customizations c set appearance=c.appearance||jsonb_build_object('paint',a.paint,'plateStyle',a.plate_style,'plateNames',a.plate_names,'frame',a.frame,'vehicleModel',a.vehicle_model),version=version+1 from public.kiyi_appearance a,public.kiyi_vehicles v where a.user_id=u and v.owner=u and v.is_primary and c.vehicle_id=v.id;
 end if;return r;
end$$;
revoke all on function kiyi_private.command(text,jsonb) from public,anon;grant execute on function kiyi_private.command(text,jsonb) to authenticated;
-- Preserve old guards, only replace the obsolete media-type rejection with server-attested media.
do $$declare d text;begin
 select pg_get_functiondef('kiyi_private.command_stage1(text,jsonb)'::regprocedure) into d;
 d=replace(d,'metadata->>''mimetype'' in (''audio/webm'',''audio/mp4'')','(metadata->>''mimetype'' in (''audio/webm'',''audio/mp4'') or exists(select 1 from kiyi_private.media_registry r where r.path=payload->>''media'' and r.owner=u and r.state=''ready''))');
 execute d;
end$$;
commit;
